func (this *Cryptomus) ParseMarket(market any) map[string]any {
	//
	//     {
	//         "id": "01JHN5EFT64YC4HR9KCGM5M65D",
	//         "symbol": "POL_USDT",
	//         "baseCurrency": "POL",
	//         "quoteCurrency": "USDT",
	//         "baseMinSize": "1.00000000",
	//         "quoteMinSize": "5.00000000",
	//         "baseMaxSize": "50000.00000000",
	//         "quoteMaxSize": "10000000000.00000000",
	//         "basePrec": "1",
	//         "quotePrec": "4"
	//     }
	//
	var marketId *string = this.SafeString(market, "symbol")
	if marketId == nil {
		panic(ExchangeError(this.Id + " parseMarket() missing marketId"))
	}
	var parts []string = strings.Split(*marketId, "_")
	var baseId *string = this.SafeString(parts, 0)
	var quoteId *string = this.SafeString(parts, 1)
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var fees map[string]any = SafeMapTyped(this.Fees, "trading")
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"symbol":         *base + "/" + *quote,
		"base":           base,
		"quote":          quote,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"active":         true,
		"type":           "spot",
		"subType":        nil,
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"contract":       false,
		"settle":         nil,
		"settleId":       nil,
		"contractSize":   nil,
		"linear":         nil,
		"inverse":        nil,
		"taker":          this.SafeNumber(fees, "taker"),
		"maker":          this.SafeNumber(fees, "maker"),
		"percentage":     this.SafeBool(fees, "percentage"),
		"tierBased":      nil,
		"feeSide":        this.SafeString(fees, "feeSide"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quotePrec"))),
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "basePrec"))),
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": this.SafeNumber(market, "quoteMinSize"),
				"max": this.SafeNumber(market, "quoteMaxSize"),
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "baseMinSize"),
				"max": this.SafeNumber(market, "baseMaxSize"),
			},
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}

/**
 * @method
 * @name cryptomus#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://doc.cryptomus.com/personal/market-cap/assets
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Cryptomus) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Cryptomus) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetV1ExchangeMarketAssets(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         'state': '0',
	//         'result': [
	//             {
	//                 'currency_code': 'USDC',
	//                 'network_code': 'bsc',
	//                 'can_withdraw': true,
	//                 'can_deposit': true,
	//                 'min_withdraw': '1.00000000',
	//                 'max_withdraw': '10000000.00000000',
	//                 'max_deposit': '10000000.00000000',
	//                 'min_deposit': '1.00000000'
	//             },
	//             ...
	//         ]
	//     }
	//
	var coins []any = SafeListTyped(response, "result")
	var groupedById map[string]any = this.GroupBy(coins, "currency_code")
	var groupedArray []any = nil
	if groupedById != nil {
		groupedArray = make([]any, 0, len(groupedById))
		for _, objectValue := range groupedById {
			groupedArray = append(groupedArray, objectValue)
		}
	}

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(groupedArray)}
	return nil
}
func (this *Cryptomus) ParseCurrency(rawCurrency any) map[string]any {
	// currency here is array of networks
	var id *string = nil // all entries have same id, as they were grouped by
	var code any = nil
	var networks map[string]any = map[string]any{}
	for i := 0; i < GetArrayLength(rawCurrency); i++ {
		var networkEntry map[string]any = SafeMapTyped(rawCurrency, i)
		// set ID on first loop
		if id == nil {
			id = this.SafeString(networkEntry, "currency_code")
			if derefPtr := this.SafeCurrencyCode(id); derefPtr != nil {
				code = *derefPtr
			} else {
				code = nil
			}
		}
		var networkId *string = this.SafeString(networkEntry, "network_code")
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		if networkCode != nil {
			networks[*networkCode] = map[string]any{
				"id":      networkId,
				"network": networkCode,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": this.SafeNumber(networkEntry, "min_withdraw"),
						"max": this.SafeNumber(networkEntry, "max_withdraw"),
					},
					"deposit": map[string]any{
						"min": this.SafeNumber(networkEntry, "min_deposit"),
						"max": this.SafeNumber(networkEntry, "max_deposit"),
					},
				},
				"active":    nil,
				"deposit":   this.SafeBool(networkEntry, "can_deposit"),
				"withdraw":  this.SafeBool(networkEntry, "can_withdraw"),
				"fee":       nil,
				"precision": nil,
				"info":      networkEntry,
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":       id,
		"code":     code,
		"networks": networks,
		"info":     rawCurrency,
	})
}

